#include <cstdio>

#include "beat_features.h"
#include "tinyml_model.h"

// Generated by the training pipeline. Included ONLY here: they define the
// model's arrays and functions, so including them anywhere else would copy
// the model into the flash again (or fail to link).
#include "models/svm_classifier.h"
#include "models/svm_classifier_scaler.h"

const char kModelName[] = "SVM";

bool init_model()
{
    return true;
}

int classify(const float *beat, const float *rr)
{
    float features[kFeatureCount];
    build_features(beat, rr, features);

    float scaled[kFeatureCount];
    for (int i = 0; i < kFeatureCount; ++i) {
        scaled[i] = (features[i] - svm_scaler_mean[i]) / svm_scaler_scale[i];
    }
    return svm_predict(scaled);
}

void print_model_info()
{
    // Classic models live in the binary itself: no runtime arena. Model
    // size is SVM_MODEL_BYTES (svm_classifier.h): the actual flash
    // footprint of the support vectors/coefficients/intercepts arrays.
    // RAM: svm_predict() keeps the kernel value of every support vector in
    // a static float array (kvalue), the SVM's equivalent of an arena.
    std::printf("INFO,%s,%u,%u\n", kModelName,
                static_cast<unsigned>(SVM_MODEL_BYTES),
                static_cast<unsigned>(SVM_SUPPORT_VECTOR_COUNT * sizeof(float)));
    std::fflush(stdout);
}
